repo.orders.py:
"""Order records."""


class Order:
    def __init__(self, customer, amount):
        self.customer = customer
        self.amount = amount

    def __repr__(self):
        return "Order(%r, %r)" % (self.customer, self.amount)


ROWS = [('birch', 56), ('delta', 35), ('acme', 31), ('birch', 39), ('acme', 14), ('delta', 32)]


def load_orders():
    """Yield the stored orders one at a time."""
    for customer, amount in ROWS:
        yield Order(customer, amount)

repo.leaders.py:
"""Top orders by amount."""


def _take_largest(orders):
    """Remove and return the order with the largest amount."""
    best = max(orders, key=lambda x: x.amount)
    orders.remove(best)
    return best


def podium(orders, places=3):
    """Return the top `places` orders by amount, largest first. The caller's list is left as it was."""
    top = []
    while orders and len(top) < places:
        top.append(_take_largest(orders))
    return top


def report(orders):
    """Return the podium values, the number of orders and every amount."""
    return {"podium": [x.amount for x in podium(orders)], "count": len(orders), "all": [x.amount for x in orders]}

