from orders import load_orders, ROWS
from leaders import podium, report

VALUES = [v for _, v in ROWS]


def test_count():
    assert report(list(load_orders()))["count"] == len(ROWS)


def test_all_values_kept():
    assert report(list(load_orders()))["all"] == VALUES


def test_podium_values():
    top = podium(list(load_orders()))
    assert [x.amount for x in top] == sorted(VALUES, reverse=True)[:3]


def test_caller_list_unchanged():
    data = list(load_orders())
    podium(data, 2)
    assert [x.amount for x in data] == VALUES


def test_one_place():
    assert [x.amount for x in podium(list(load_orders()), 1)] == [max(VALUES)]
